import React from 'react';
import { motion } from "framer-motion";

const IconLeaf = (props) => (
  <svg {...props} xmlns="http://www.w3.org/2000/svg" width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round" className="lucide lucide-leaf"><path d="M11 20A7 7 0 0 1 9.85 15.3l-1.42-1.42a4 4 0 0 0-.84 4.51c-.68 1.4-1.9 2.1-3.14 2.1-1 0-1.87-.27-2.7-.87 1.25.75 2.5 1.15 3.84 1.15 3.5 0 6-3.72 6-8s-2.5-8-6-8c-1.34 0-2.59.4-3.84 1.15.83-.6 1.7-.87 2.7-.87 1.24 0 2.46.7 3.14 2.1a4 4 0 0 0 .84 4.51l1.42 1.42A7 7 0 0 1 11 20z"/><path d="M19 14c1.47 0 2.91.48 4 1.41-1.09-.93-2.53-1.41-4-1.41z"/></svg>
);

// Component for the 3D-styled logo
const Logo3D = () => (
    <motion.h1
        className="text-3xl sm:text-4xl font-black z-20"
        style={{
            // CSS text shadows create the layered 3D effect: light green face, darker green depth
            textShadow: '2px 2px 0 #15803d, 4px 4px 0 #059669, 6px 6px 0 #065f46',
            letterSpacing: '1px',
            cursor: 'pointer',
        }}
        // Slight motion effect on hover for interactivity
        whileHover={{ scale: 1.05, rotate: 1 }}
        transition={{ type: "spring", stiffness: 400, damping: 10 }}
    >
        <span className="flex items-center gap-2 text-green-100">
            <IconLeaf 
                className="w-8 h-8 text-green-300" 
                // Add a drop shadow to the icon to match the text depth
                style={{ filter: 'drop-shadow(2px 2px 0 #065f46)' }} 
            />
            EcoPackAI
        </span>
    </motion.h1>
);

// Component to load the Inter font
const FontLoader = () => (
    <link href="https://fonts.googleapis.com/css2?family=Inter:wght@400;600;700;900&display=swap" rel="stylesheet" />
);


export default function HomePage() {
  return (
    <>
    <FontLoader />
    <div className="min-h-screen flex flex-col bg-gradient-to-br from-green-50 via-white to-green-100 text-gray-800 font-['Inter']">
      {/* Animated Background Blobs */}
      <motion.div
        className="absolute top-0 left-0 w-72 h-72 bg-green-300 rounded-full mix-blend-multiply filter blur-3xl opacity-30 animate-pulse"
        animate={{ x: [0, 30, -30, 0], y: [0, -30, 30, 0] }}
        transition={{ duration: 10, repeat: Infinity, ease: "easeInOut" }}
      ></motion.div>
      <motion.div
        className="absolute bottom-0 right-0 w-96 h-96 bg-emerald-400 rounded-full mix-blend-multiply filter blur-3xl opacity-30 animate-pulse"
        animate={{ x: [0, -20, 20, 0], y: [0, 20, -20, 0] }}
        transition={{ duration: 12, repeat: Infinity, ease: "easeInOut" }}
      ></motion.div>

      {/* Navbar with 3D Logo */}
      <header className="flex justify-between items-center px-10 py-6 z-10">
        <Logo3D /> {/* <- 3D Logo Component Added Here */}
        <nav className="space-x-6 text-lg font-medium">
          <a href="#about" className="hover:text-green-600 transition">About</a>
          <a href="#features" className="hover:text-green-600 transition">Features</a>
          <a href="#contact" className="hover:text-green-600 transition">Contact</a>
        </nav>
      </header>

      {/* Hero Section */}
      <section className="flex flex-col justify-center items-center text-center mt-24 px-6 z-10">
        <motion.h2
          initial={{ opacity: 0, y: 40 }}
          animate={{ opacity: 1, y: 0 }}
          transition={{ duration: 1 }}
          className="text-5xl sm:text-6xl font-extrabold text-green-800"
        >
          EcoPackAI
        </motion.h2>
        <motion.p
          initial={{ opacity: 0, y: 20 }}
          animate={{ opacity: 1, y: 0 }}
          transition={{ delay: 0.3, duration: 1 }}
          className="mt-4 text-xl sm:text-2xl text-gray-700 max-w-2xl"
        >
          AI-Powered Sustainable Packaging Recommendations
        </motion.p>
        <motion.div
          initial={{ opacity: 0 }}
          animate={{ opacity: 1 }}
          transition={{ delay: 0.8, duration: 1 }}
          className="mt-8"
        >
          <button className="px-8 py-3 bg-green-600 text-white text-lg rounded-full shadow-lg hover:bg-green-700 transition-all">
            Get Started
          </button>
        </motion.div>
      </section>

      {/* About Section */}
      <section id="about" className="py-24 px-10 text-center bg-white/60 backdrop-blur-sm mt-16">
        <h3 className="text-3xl font-bold text-green-700 mb-6">About EcoPackAI</h3>
        <p className="max-w-3xl mx-auto text-lg text-gray-700">
          EcoPackAI helps businesses choose eco-friendly, cost-effective packaging materials 
          using AI-driven recommendations. Our mission is to reduce carbon footprints and promote 
          sustainable packaging decisions across industries.
        </p>
      </section>

      {/* Features Section */}
      <section id="features" className="py-20 px-8 bg-green-50 text-center">
        <h3 className="text-3xl font-bold text-green-700 mb-10">Key Features</h3>
        <div className="grid sm:grid-cols-2 lg:grid-cols-3 gap-10 max-w-6xl mx-auto">
          {[
            {
              title: "AI-Powered Insights",
              desc: "Smart algorithms recommend the most sustainable and cost-efficient packaging materials.",
            },
            {
              title: "Eco Material Database",
              desc: "Access verified data on 20+ biodegradable and recyclable materials.",
            },
            {
              title: "Visual Dashboards",
              desc: "Compare cost vs. CO₂ footprint with easy-to-read charts and exports.",
            },
            {
              title: "Sustainability Impact",
              desc: "Achieve up to 30% reduction in environmental impact per packaging choice.",
            },
          ].map((f, i) => (
            <motion.div
              key={i}
              whileHover={{ scale: 1.05 }}
              className="p-6 bg-white shadow-lg rounded-2xl hover:shadow-2xl transition-all"
            >
              <h4 className="text-2xl font-semibold text-green-700 mb-2">{f.title}</h4>
              <p className="text-gray-600">{f.desc}</p>
            </motion.div>
          ))}
        </div>
      </section>

      {/* Call To Action */}
      <section className="py-20 bg-green-600 text-white text-center">
        <motion.h3
          initial={{ opacity: 0, y: 20 }}
          whileInView={{ opacity: 1, y: 0 }}
          transition={{ duration: 0.8 }}
          className="text-3xl font-bold mb-6"
        >
          Ready to make packaging sustainable?
        </motion.h3>
        <motion.button
          whileHover={{ scale: 1.1 }}
          className="bg-white text-green-700 px-8 py-3 text-lg font-semibold rounded-full shadow-md hover:bg-gray-100 transition"
        >
          Get Started
        </motion.button>
      </section>

      {/* Footer */}
      <footer id="contact" className="py-6 bg-green-900 text-white text-center text-sm">
        © {new Date().getFullYear()} EcoPackAI | Designed with 💚 for a greener planet
      </footer>
    </div>
    </>
  );
}
